mapper.select:
SELECT EMPNO, EMP_NM, DEPT_CD, PART_CD FROM HR_DEVELOPER WHERE STATUS_CD = '01'
AND PART_CD = #{part}
ORDER BY EMP_NM

SELECT h.PART_CD AS PART_CD, h.DEPT_CD AS DEPT_CD, d.SR_CLS AS SR_CLS, SUM(d.SR_CNT) AS SR_CNT, SUM(d.JOB_MM) AS JOB_MM FROM DASH_DEV_AGG d INNER JOIN HR_DEVELOPER h ON d.EMPNO = h.EMPNO WHERE d.PERIOD_YM = #{period} AND h.STATUS_CD = '01'
AND h.PART_CD = #{part}
GROUP BY h.PART_CD, h.DEPT_CD, d.SR_CLS ORDER BY h.PART_CD, h.DEPT_CD, d.SR_CLS
